import re

def extract_news_stories(text):
    news_stories = []
    pattern = re.compile(r"^(?P<title>[^<]+)\s*\[.*?\]$")
    for match in pattern.finditer(text):
        title = match.group("title")
        story = match.group("content")
        if title:
            news_stories.append(f"<h2>{title}</h2>")
            news_stories.append(f"<p>{story}</p>")
